INSERT INTO words (id, term, context, definition, usage_explanation, sample_sentences, register, related_words, category, created_at, status) VALUES ('d837fc77-3a51-4ebe-9b47-6695d1eba018', 'diabolical', 'when people are playing guess celebrities and the person who couldn''t guess his said "why are you giving this diabolical"', 'In this context, ''diabolical'' is British slang meaning terrible, awful, or of very poor quality. It can also mean extremely difficult or confusing. In its original sense, it means relating to the devil or something evil.', 'In the context given, the person is complaining that the clues or hints being given are terrible and unhelpful — essentially saying ''why are you giving such awful/useless clues?'' This is a very common British informal usage where ''diabolical'' simply means shockingly bad or poor quality.', '["The directions he gave me were diabolical — I ended up completely lost.", "Her impression of the celebrity was diabolical; nobody could guess who it was supposed to be.", "The service at that restaurant was absolutely diabolical, we waited an hour for our food."]', 'informal', '["terrible", "atrocious", "dreadful", "rubbish"]', 'social', '2026-06-08 00:09:34.411798+00', 'new') ON CONFLICT (id) DO NOTHING;
